// ── Pull original webhook body ──────────────────────────────
const webhookBody = $('Webhook - Quiz Generator').item.json.body
                 || $('Webhook - Quiz Generator').item.json;

// ── Extract RAG chunks from backend search result ───────────
const result = $input.first().json;
const chunks = result.data || result.matches || result.results || [];

let curriculumContext = '';
if (Array.isArray(chunks) && chunks.length > 0) {
  curriculumContext = chunks
    .map((item, i) => `[${i + 1}] ${item.chunkText || item.text || item.content || ''}`)
    .join('\n\n');
} else {
  curriculumContext = 'No matching curriculum context found in Google Drive.';
}

// ── Return merged body – curriculumContext now populated ─────
return [{ json: { ...webhookBody, curriculumContext, ragChunksFound: chunks.length, ragInjected: true } }];

// body arrives with curriculumContext already injected by the RAG pipeline
const body = $input.item.json;
const questionType = body.questionType || 'mcq';
const typeInstruction = questionType === 'closed_ended'
  ? 'Generate close-ended questions with direct short answers.'
  : 'Generate multiple choice questions with four options each.';

const prompt = `
You are Learnify Quiz Generator.

Subject: ${body.subject}
Topic: ${body.topic}
Question Type: ${questionType}

Curriculum Context (Retrieved from Google Drive RAG – use as primary source):
${body.curriculumContext || 'No curriculum context available.'}

Scanned Note:
${body.extractedText || 'No scanned note provided.'}

Task:
${typeInstruction}

Return valid JSON only in this format:
{
  "studentId": "${body.studentId}",
  "noteId": "${body.noteId}",
  "subject": "${body.subject}",
  "topic": "${body.topic}",
  "questionType": "${questionType}",
  "ragChunksUsed": ${body.ragChunksFound || 0},
  "questions": [
    { "question": "", "options": [], "correctAnswer": "", "explanation": "", "type": "${questionType}" }
  ]
}

Rules:
- Generate 10 questions.
- Prioritise content found in the Curriculum Context.
- Align difficulty with WAEC/NECO/JAMB syllabus level.
- Do not include markdown.
`;
return [{ json: { ...body, prompt } }];

const response = $input.first().json;
let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
text = text.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(text); } catch (error) { throw new Error('Gemini did not return valid quiz JSON: ' + text); }
return [{ json: parsed }];
